        private void SetConnectionFrom(ScenarioConnection c, object val) { if (int.TryParse(val?.ToString(), out int idx) && idx >= 0) { c.FromDevice = Item.Devices[idx]; c.FromDeviceId = c.FromDevice.Id; } }
        private void SetConnectionTo(ScenarioConnection c, object val) { if (int.TryParse(val?.ToString(), out int idx) && idx >= 0) { c.ToDevice = Item.Devices[idx]; c.ToDeviceId = c.ToDevice.Id; } }

        private void HandleCanvasClick(MouseEventArgs e)
        {
            if (selectedDevice != null) { selectedDevice.MapX = (int)e.OffsetX; selectedDevice.MapY = (int)e.OffsetY; StateHasChanged(); }
        }

        private async Task UploadDocumentToDb(InputFileChangeEventArgs e, ScenarioDocument doc)
        {
            try
            {
                var file = e.File;
                if (file == null) return;

                long maxFileSize = 50 * 1024 * 1024; // 50 МБ
                if (file.Size > maxFileSize)
                {
                    NotificationService.Notify(NotificationSeverity.Warning, "Ошибка", "Файл больше 50 МБ.");
                    return;
                }

                // Безопасное чтение без MemoryStream и CopyToAsync
                var buffer = new byte[file.Size];
                await using var stream = file.OpenReadStream(maxAllowedSize: maxFileSize);

                int totalRead = 0;
                while (totalRead < file.Size)
                {
                    int read = await stream.ReadAsync(buffer, totalRead, (int)file.Size - totalRead);
                    if (read == 0) break;
                    totalRead += read;
                }

                doc.Content = buffer;
                doc.FileName = file.Name;
                doc.ContentType = string.IsNullOrWhiteSpace(file.ContentType) ? "application/octet-stream" : file.ContentType;

                if (string.IsNullOrWhiteSpace(doc.Title))
                    doc.Title = file.Name;

                NotificationService.Notify(NotificationSeverity.Success, "Успех", "Документ прикреплен");
            }
            catch (TaskCanceledException)
            {
                NotificationService.Notify(NotificationSeverity.Warning, "Внимание", "Чтение прервано браузером. Попробуйте еще раз.");
            }
            catch (Exception ex)
            {
                NotificationService.Notify(NotificationSeverity.Error, "Ошибка загрузки", ex.Message);
            }
        }

        private async Task OnSave()
        {
            Item.SchemaPath = "INTERNAL_BUILDER";
            if (isIndividual) { Item.AllowedTeamIds = null; Item.AllowedUserIds = addedUsers.Any() ? string.Join(",", addedUsers.Select(u => u.Id)) : null; Item.Scope = string.IsNullOrEmpty(Item.AllowedUserIds) ? VisibilityScope.Public : VisibilityScope.GroupOnly; }
            else { Item.AllowedUserIds = null; Item.AllowedTeamIds = addedTeams.Any() ? string.Join(",", addedTeams.Select(t => t.Id)) : null; Item.Scope = VisibilityScope.TeamOnly; }

            using var context = await ContextFactory.CreateDbContextAsync();

            if (Item.Id == 0)
            {
                // Сохраняем автора
                var authState = await AuthStateProvider.GetAuthenticationStateAsync();
                Item.AuthorId = authState.User.FindFirst(ClaimTypes.NameIdentifier)?.Value;

                context.Scenarios.Add(Item);
            }
            else
            {
                context.Scenarios.Update(Item);
            }

            await context.SaveChangesAsync();
            CatalogUpdateService.NotifyCatalogChanged();
            NotificationService.Notify(NotificationSeverity.Success, "Успех", "Сценарий сохранен!");
            NavigationManager.NavigateTo("scenario");
        }

        private void Cancel() => NavigationManager.NavigateTo("scenario");
